function hairs(t,s=1,cut=0){let h='';for(let i=0;i<7;i++){const x=-180+i*60;const len=cut?60:220;h+=`<path d="M${x},0L${x},-30" stroke="#5B3A2A" stroke-width="16"/><path d="M${x},-30Q${x+(cut?0:10)},${-30-len/2} ${x+(cut?0:-6)},${-30-len}" stroke="#2E2430" stroke-width="${cut?18:14}" fill="none" stroke-linecap="${cut?'butt':'round'}"/>`;}
 return g(`scale(${s})`,`<rect x="-240" y="0" width="480" height="140" fill="#F3C9A8" stroke="${OL}" stroke-width="7"/><path d="M-240,0L240,0" stroke="#D9A98A" stroke-width="6"/>`+h+Array.from({length:7},(_,i)=>`<ellipse cx="${-180+i*60}" cy="40" rx="18" ry="26" fill="#E8A58C" stroke="${OL}" stroke-width="4"/>`).join(''));}
function carrot(s=1,r=0){return g(`scale(${s}) rotate(${r})`,`<path d="M-50,-120Q0,-140 50,-120L10,200Q0,220 -10,200Z" fill="#F2913D" stroke="${OL}" stroke-width="7" stroke-linejoin="round"/><path d="M-30,-60L5,-50M-20,10L10,20M-10,80L8,88" stroke="#C96A1F" stroke-width="6" stroke-linecap="round"/><path d="M0,-130C-40,-200 -60,-210 -40,-240M0,-130C0,-200 10,-230 0,-260M0,-130C40,-200 60,-210 40,-240" stroke="#3BB273" stroke-width="16" fill="none" stroke-linecap="round"/>`);}
function goldfish(t,s=1,o={}){const w=Math.sin(t*6)*10;return g(`scale(${s})`,`<path d="M110,0L200,${fmt(-70+w)}L190,0L200,${fmt(70+w)}Z" fill="#F2913D" stroke="${OL}" stroke-width="7" stroke-linejoin="round"/><ellipse cx="0" cy="0" rx="130" ry="90" fill="#F6A13D" stroke="${OL}" stroke-width="7"/><path d="M-20,-85Q20,-150 70,-80" fill="#F2913D" stroke="${OL}" stroke-width="6"/><circle cx="-70" cy="-20" r="22" fill="#fff" stroke="${OL}" stroke-width="5"/><circle cx="-74" cy="-20" r="11" fill="#2E2430"/><path d="M-120,20Q-105,35 -95,20" stroke="#2E2430" stroke-width="6" fill="none"/>${o.bubble?Array.from({length:3},(_,i)=>{const ph=(t*0.8+i/3)%1;return `<circle cx="${-150-i*10}" cy="${fmt(-60-ph*160)}" r="${12+i*4}" fill="none" stroke="#BFE6F7" stroke-width="4" opacity="${fmt(1-ph)}"/>`;}).join(''):''}`);}
function fishBowl(t,s=1){return g(`scale(${s})`,`<path d="M-200,-180Q-300,0 -180,190L180,190Q300,0 200,-180Z" fill="#9FD8F2" opacity=".55" stroke="#fff" stroke-width="10"/><path d="M-220,-180L220,-180" stroke="#fff" stroke-width="14" stroke-linecap="round"/><path d="M-170,170Q0,140 170,170L160,190L-160,190Z" fill="#E9D4A8"/>`);}
function glassW(t,s=1,lvl=0.7){const top=160-320*lvl;return g(`scale(${s})`,`<clipPath id="gw${Math.round(s*100)}"><path d="M-110,-170L110,-170L90,170L-90,170Z"/></clipPath><g clip-path="url(#gw${Math.round(s*100)})"><rect x="-120" y="${fmt(top)}" width="240" height="400" fill="#5DB7EA" opacity=".8"/></g><path d="M-110,-170L110,-170L90,170L-90,170Z" fill="#fff" fill-opacity=".25" stroke="${OL}" stroke-width="7" stroke-linejoin="round"/><path d="M-70,-130L-60,120" stroke="#fff" stroke-width="10" opacity=".6"/>`);}
function radar(t,s=1){const a=t*120;return g(`scale(${s})`,`<circle r="160" fill="#14301F" stroke="#3BB273" stroke-width="8"/><circle r="100" fill="none" stroke="#3BB273" stroke-width="4" opacity=".6"/><circle r="50" fill="none" stroke="#3BB273" stroke-width="4" opacity=".6"/><path d="M0,0L0,-160" stroke="#7BC96F" stroke-width="8" transform="rotate(${fmt(a)})"/><circle cx="60" cy="-70" r="12" fill="#E5383B" opacity="${fmt(0.5+0.5*Math.sin(t*5))}"/>`);}
function urineChart(s=1){const c=['#FFF7C2','#FDEB8C','#F8D648','#E9B627','#C98E12'];return g(`scale(${s})`,c.map((x,i)=>`<rect x="-80" y="${-250+i*100}" width="160" height="90" rx="16" fill="${x}" stroke="${OL}" stroke-width="6"/>`).join(''));}
