function catBody(t,s=1,rot=0,col='#F2A541'){return g(`scale(${s}) rotate(${fmt(rot)})`,`<ellipse cx="0" cy="40" rx="150" ry="85" fill="${col}" stroke="${OL}" stroke-width="7"/><path d="M140,30C220,0 230,-80 200,-110" stroke="${col}" stroke-width="28" fill="none" stroke-linecap="round"/><path d="M140,30C220,0 230,-80 200,-110" stroke="${OL}" stroke-width="5" fill="none" stroke-linecap="round" opacity=".5"/>${[-100,-40,40,100].map(x=>`<rect x="${x-16}" y="90" width="32" height="80" rx="14" fill="${col}" stroke="${OL}" stroke-width="6"/>`).join('')}<g transform="translate(-140,-40) scale(.75)">${catFace(1)}</g>`);}
function camel(t,s=1,o={}){const hump=o.fat?1.15:1;return g(`scale(${s})`,`<ellipse cx="0" cy="40" rx="190" ry="90" fill="#D9A55B" stroke="${OL}" stroke-width="7"/><path d="M-90,-20C-80,${fmt(-150*hump)} 60,${fmt(-150*hump)} 80,-20Z" fill="#C98F45" stroke="${OL}" stroke-width="7"/>${[-140,-70,70,140].map(x=>`<rect x="${x-14}" y="100" width="28" height="140" rx="10" fill="#D9A55B" stroke="${OL}" stroke-width="6"/>`).join('')}<path d="M-170,10C-230,-40 -240,-120 -230,-170" stroke="#D9A55B" stroke-width="50" fill="none" stroke-linecap="round"/><ellipse cx="-245" cy="-185" rx="55" ry="38" fill="#D9A55B" stroke="${OL}" stroke-width="6"/><circle cx="-250" cy="-198" r="8" fill="${OL}"/><path d="M-290,-170Q-280,-160 -270,-168" stroke="${OL}" stroke-width="4" fill="none"/>`);}
function ostrich(t,s=1,o={}){const run=o.run?Math.sin(t*16):0;const head=o.down?`<path d="M-60,-40C-120,-20 -160,60 -170,130" stroke="#E8C9B0" stroke-width="26" fill="none" stroke-linecap="round"/><ellipse cx="-175" cy="150" rx="34" ry="26" fill="#E8C9B0" stroke="${OL}" stroke-width="5"/><path d="M-205,150L-235,160" stroke="#F2A541" stroke-width="10" stroke-linecap="round"/><circle cx="-180" cy="140" r="6" fill="${OL}"/>`:`<path d="M-60,-40C-90,-120 -80,-220 -70,-280" stroke="#E8C9B0" stroke-width="26" fill="none" stroke-linecap="round"/><ellipse cx="-80" cy="-300" rx="36" ry="28" fill="#E8C9B0" stroke="${OL}" stroke-width="5"/><path d="M-112,-298L-145,-292" stroke="#F2A541" stroke-width="10" stroke-linecap="round"/><circle cx="-82" cy="-310" r="7" fill="${OL}"/>`;
 return g(`scale(${s})`,`${[-25,35].map((x,i)=>`<path d="M${x},60L${fmt(x+(i?run:-run)*40)},230" stroke="#E8C9B0" stroke-width="18" stroke-linecap="round"/>`).join('')}<ellipse cx="10" cy="0" rx="130" ry="85" fill="#2E2430" stroke="${OL}" stroke-width="7"/><path d="M110,-20C170,-40 190,20 150,40" fill="#fff" stroke="${OL}" stroke-width="5"/>${head}`);}
function eggs(s=1){return g(`scale(${s})`,`<ellipse cx="0" cy="40" rx="170" ry="50" fill="#C9A26B" stroke="${OL}" stroke-width="6"/>${[-70,0,70].map(x=>`<ellipse cx="${x}" cy="10" rx="38" ry="48" fill="#FFF6E0" stroke="${OL}" stroke-width="5"/>`).join('')}`);}
function greatWall(s=1){let tw='';for(let i=0;i<4;i++)tw+=`<rect x="${-330+i*200}" y="${-60-i*20}" width="70" height="90" fill="#B9A27A" stroke="${OL}" stroke-width="5"/>`;return g(`scale(${s})`,`<path d="M-400,40L-100,-20L120,-60L400,-110L400,-60L120,-10L-100,30L-400,90Z" fill="#C9B48A" stroke="${OL}" stroke-width="6"/>${tw}<path d="M-400,140Q0,60 400,40L400,200L-400,200Z" fill="#7BA05B" opacity=".9"/>`);}
