function walker(t,s=1,o={}){const w=o.walk?Math.sin(t*5):0;return g(`scale(${s})`,`<path d="M-20,120L${fmt(-20-w*30)},260M20,120L${fmt(20+w*30)},260" stroke="#2C4A7A" stroke-width="34" stroke-linecap="round"/><rect x="-60" y="-60" width="120" height="190" rx="40" fill="#F2F2F2" stroke="${OL}" stroke-width="7"/>${[0,1,2].map(i=>`<path d="M-60,${-20+i*50}L60,${-20+i*50}" stroke="#8FB3E0" stroke-width="12"/>`).join('')}<path d="M-55,-20L-150,-30M55,-20L150,-30" stroke="#F2C9A0" stroke-width="28" stroke-linecap="round"/><circle cy="-120" r="70" fill="#F2C9A0" stroke="${OL}" stroke-width="7"/>${o.awake?`<circle cx="-24" cy="-125" r="12" fill="${OL}"/><circle cx="24" cy="-125" r="12" fill="${OL}"/><path d="M-12,-85Q0,-75 12,-85" stroke="${OL}" stroke-width="6" fill="none"/>`:`<path d="M-38,-125Q-24,-115 -10,-125M10,-125Q24,-115 38,-125" stroke="${OL}" stroke-width="6" fill="none" stroke-linecap="round"/>`}`);}
function stairs(s=1){let p='';for(let i=0;i<5;i++)p+=`<rect x="${i*80}" y="${-i*60}" width="${400-i*80}" height="60" fill="#B98A5E" stroke="${OL}" stroke-width="5"/>`;return g(`scale(${s})`,p);}
function chameleon(t,s=1,col='#7BC96F'){return g(`scale(${s})`,`<path d="M120,40C200,40 220,140 160,150C120,155 120,110 150,110" stroke="${col}" stroke-width="30" fill="none" stroke-linecap="round"/><ellipse cx="0" cy="20" rx="150" ry="85" fill="${col}" stroke="${OL}" stroke-width="7"/><path d="M-110,-40L-60,-80L-10,-50L40,-80L90,-50" stroke="${OL}" stroke-width="6" fill="none" opacity=".4"/>${[-80,60].map(x=>`<path d="M${x},90L${x-10},150L${x+20},150" stroke="${col}" stroke-width="24" fill="none" stroke-linecap="round"/>`).join('')}<path d="M-140,-20C-220,-40 -250,30 -200,70C-170,90 -140,60 -140,40Z" fill="${col}" stroke="${OL}" stroke-width="7"/><circle cx="-180" cy="10" r="30" fill="#fff" stroke="${OL}" stroke-width="5"/><circle cx="${fmt(-185+6*Math.sin(t*2))}" cy="10" r="12" fill="${OL}"/>`);}
